// The page and its assets are one program split across requests, and the ETag only
// makes the edge keep them together. Cloudflare rewrites what it passes on (our
// `no-cache` reaches the browser as `max-age=14400`), so each first-party runtime asset
// needs a content-hashed URL rather than an old model or engine under a new page.
func TestTerminalPageStampsRuntimeVersions(t *testing.T) {
	for _, name := range []string{
		"eh-model.js",
		"eh-predict-input.js",
		"eh-predict-layout.js",
		"eh-predict-navigation.js",
		"eh-predict-actions.js",
		"eh-predict-style.js",
		"eh-predict-renderer.js",
		"eh-predict-reconcile.js",
		"eh-predict-session.js",
		"eh-status.js",
		"eh-auth.js",
		"eh-clipboard.js",
		"eh-transport.js",
		"eh-predictor.js",
		"eh-engine.js",
	} {
		t.Run(name, func(t *testing.T) {
			pattern := regexp.MustCompile(`/__console/assets/` + regexp.QuoteMeta(name) + `\?v=([0-9a-f]+)`)
			m := pattern.FindSubmatch(terminalPage)
			if m == nil {
				t.Fatalf("the served page loads %s without a content version", name)
			}

			// The stamp and ETag must identify the same embedded bytes.
			r := httptest.NewRequest(http.MethodGet, "/__console/assets/"+name, nil)
			w := httptest.NewRecorder()
			serveAsset(w, r)
			if want := `"` + string(m[1]) + `"`; w.Header().Get("Etag") != want {
				t.Errorf("page stamps v=%s, asset ETag is %s; want the content hash",
					m[1], w.Header().Get("Etag"))
			}
			if w.Code != http.StatusOK {
				t.Errorf("%s status %d, want 200", name, w.Code)
			}

			// The stamped URL serves only the bytes named by its content hash.
			r = httptest.NewRequest(http.MethodGet, "/__console/assets/"+name+"?v="+string(m[1]), nil)
			w = httptest.NewRecorder()
			serveAsset(w, r)
			if w.Code != http.StatusOK || w.Header().Get("Etag") != `"`+string(m[1])+`"` {
				t.Errorf("stamped URL: status %d, ETag %s", w.Code, w.Header().Get("Etag"))
			}

			for _, query := range []string{"?v=deadbeef", "?v=", "?v=" + string(m[1]) + "&v=" + string(m[1])} {
				r = httptest.NewRequest(http.MethodGet, "/__console/assets/"+name+query, nil)
				w = httptest.NewRecorder()
				serveAsset(w, r)
				if w.Code != http.StatusNotFound {
					t.Errorf("invalid version %q: status %d, want 404", query, w.Code)
				}
			}
		})
	}

	// Every asset the page loads is stamped, not only the engine: the vendored bundles and
	// fonts are the same program and get the same four-hour skew when they change.
	refs := strings.Count(string(terminalPage), "/__console/assets/")
	if stamped := strings.Count(string(terminalPage), "?v="); refs < 2 || stamped != refs {
		t.Errorf("page has %d asset references and %d stamps, want every reference stamped", refs, stamped)
	}
}

// clipboardHarness loads eh-clipboard.js (the path in argv[2]) into a stand-in browser,
// copies "hello" through OSC 52 once per scenario, and prints the notice the page showed
// and the messages it sent its parent. A scenario sets the clipboard API the page finds
// and how each write settles; "selection" ones copy with a mouse selection pending, as
// tmux's copy does.
const clipboardHarness = `'use strict';
var fs = require('fs');
var clipboard = new Function(fs.readFileSync(process.argv[2], 'utf8') + '\nreturn EnvHavenConsoleClipboard;')();

function resolves() { return Promise.resolve(); }
function rejects() { return Promise.reject(new Error('NotAllowedError')); }
function Item() {}

var scenarios = {
  landed: { secure: true, api: { writeText: resolves } },
  refused: { secure: true, api: { writeText: rejects } },
  plainHTTP: { secure: false },
  noClipboard: { secure: true },
  selectionLanded: { secure: true, mouseup: true, ClipboardItem: Item, api: { write: resolves, writeText: rejects } },
  selectionRefused: { secure: true, mouseup: true, ClipboardItem: Item, api: { write: rejects, writeText: rejects } },
  embedded: { secure: true, embedded: true, api: { writeText: rejects } }
};

function run(s) {
  var noticeEl = { textContent: '', classList: { add: function () {}, remove: function () {} } };
  var listeners = {}, osc = null, parent = [];
  clipboard.create({
    window: {
      isSecureContext: s.secure,
      navigator: { clipboard: s.api },
      document: { getElementById: function () { return noticeEl; } }
    },
    term: {
      parser: { registerOscHandler: function (code, handler) { if (code === 52) osc = handler; } },
      hasSelection: function () { return false; }
    },
    termEl: { addEventListener: function (type, listener) { listeners[type] = listener; } },
    timers: { setTimeout: function () { return 1; }, clearTimeout: function () {} },
    Blob: function () {},
    ClipboardItem: s.ClipboardItem,
    Uint8Array: Uint8Array,
    TextDecoder: TextDecoder,
    atob: function (value) { return atob(value); },
    embedded: !!s.embedded,
    toParent: function (message) { parent.push(message.type); }
  });
  if (s.mouseup) listeners.mouseup();
  osc('c;' + Buffer.from('hello').toString('base64'));
  return new Promise(function (resolve) { setTimeout(resolve, 0); }).then(function () {
    return { notice: noticeEl.textContent, parent: parent };
  });
}

(async function () {
  var out = {};
  for (var name of Object.keys(scenarios)) out[name] = await run(scenarios[name]);
  process.stdout.write(JSON.stringify(out));
})();
`

// TestClipboardNoticeFollowsTheWrite runs the page's clipboard module in a JS runtime
// against a stand-in browser. Top-level, a copy is announced only once a clipboard write
// has landed, and a copy that did not land says why: the browser refused the write, or it
// gives a page served over plain HTTP no clipboard at all. Embedded, the dashboard writes
// and announces, so the page hands it the text and stays quiet.
func TestClipboardNoticeFollowsTheWrite(t *testing.T) {
	var runtime string
	for _, name := range []string{"bun", "node"} {
		if path, err := exec.LookPath(name); err == nil {
			runtime = path
			break
		}
	}
	if runtime == "" {
		t.Skip("bun or node is needed to run the page's clipboard module")
	}
	src, err := assetsFS.ReadFile("ui/assets/eh-clipboard.js")
	if err != nil {
		t.Fatal(err)
	}
	dir := t.TempDir()
	asset, harness := filepath.Join(dir, "eh-clipboard.js"), filepath.Join(dir, "harness.cjs")
	if err := os.WriteFile(asset, src, 0o600); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(harness, []byte(clipboardHarness), 0o600); err != nil {
		t.Fatal(err)
	}
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	out, err := exec.CommandContext(ctx, runtime, harness, asset).Output()
	if err != nil {
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			t.Fatalf("%s harness: %v\n%s", filepath.Base(runtime), err, exitErr.Stderr)
		}
		t.Fatalf("%s harness: %v", filepath.Base(runtime), err)
	}
	var got map[string]struct {
		Notice string   `json:"notice"`
		Parent []string `json:"parent"`
	}
	if err := json.Unmarshal(out, &got); err != nil {
		t.Fatalf("harness output %q: %v", out, err)
	}

	const copied = "Terminal copied 5 characters to the clipboard"
	const refused = "Clipboard left unchanged: the browser refused the write"
	for name, want := range map[string]string{
		"landed":           copied,
		"selectionLanded":  copied,
		"refused":          refused,
		"selectionRefused": refused,
		"plainHTTP":        "Clipboard left unchanged: the browser allows the clipboard only over HTTPS",
		"noClipboard":      "Clipboard left unchanged: this browser gives the page no clipboard",
		"embedded":         "",
	} {
		if got[name].Notice != want {
			t.Errorf("%s: notice %q, want %q", name, got[name].Notice, want)
		}
	}
	if sent := got["embedded"].Parent; len(sent) != 1 || sent[0] != "envhaven-console:clipboard" {
		t.Errorf("embedded: sent the dashboard %v, want the copied text", sent)
	}
}

// Without a caching rule of our own an intermediary invents one: measured against a
// managed workspace, Cloudflare applied a four-hour default TTL to the engine and served
// the previous image's copy alongside the new image's page, and a client hard reload did
// not clear it. So the handler states the rule and supplies the validator that makes
// obeying it cheap.
func TestAssetsCacheHeaders(t *testing.T) {
	h := http.HandlerFunc(serveAsset)

	get := func(path, ifNoneMatch string) *httptest.ResponseRecorder {
		r := httptest.NewRequest(http.MethodGet, "/__console/assets/"+path, nil)
		if ifNoneMatch != "" {
			r.Header.Set("If-None-Match", ifNoneMatch)
		}
		w := httptest.NewRecorder()
		h.ServeHTTP(w, r)
		return w
	}

	predictor := get("eh-predictor.js", "")
	if predictor.Code != http.StatusOK {
		t.Fatalf("predictor: status %d, want 200", predictor.Code)
	}
	if got := predictor.Header().Get("Cache-Control"); got != "no-cache" {
		t.Errorf("predictor Cache-Control = %q, want %q — a cache with no instruction picks its own", got, "no-cache")
	}
	tag := predictor.Header().Get("Etag")
	if tag == "" {
		t.Fatal("predictor served with no ETag, so every revalidation costs the whole file")
	}

	// The validator has to actually validate, or `no-cache` means re-downloading
	// the controller on every page load rather than a 304.
	if again := get("eh-predictor.js", tag); again.Code != http.StatusNotModified {
		t.Errorf("If-None-Match %s: status %d, want 304", tag, again.Code)
	}
	// Cloudflare weakens a strong tag when it recompresses .js, so the browser behind
	// the edge revalidates with W/"...": that has to be a 304 too, or every edge
	// revalidation downloads the file.
	if weak := get("eh-predictor.js", "W/"+tag); weak.Code != http.StatusNotModified {
		t.Errorf("If-None-Match W/%s: status %d, want 304", tag, weak.Code)
	}

	// Derived from the bytes, not a constant: two different files must not share a tag,
	// or a changed engine would revalidate as unchanged.
	other := get("xterm.css", "").Header().Get("Etag")
	if other == "" || other == tag {
		t.Errorf("xterm.css ETag = %q, predictor = %q — ETags must be per-content", other, tag)
	}
}
